using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace MyProjectManagement;
public static class ActivityTypes {
 public static JsonArray Catalog(JsonObject settings)=>settings["activityTypes"] is JsonArray rows?(JsonArray)rows.DeepClone():new JsonArray(new[]{("implementation","New Implementation"),("amc","AMC"),("warranty","Warranty"),("office","Office")}.Select(t=>(JsonNode)new JsonObject{["id"]=t.Item1,["name"]=t.Item2,["active"]=true}).ToArray());
 public static string Id(JsonNode? row,string field="typeId")=>J.S(row,field) is {Length:>0} id?id:"implementation";
 public static bool Exists(JsonObject settings,string id,bool active=false)=>Catalog(settings).OfType<JsonObject>().Any(t=>J.S(t,"id")==id&&(!active||J.B(t,"active",true)));
 public static void ValidateSettings(JsonObject before,JsonObject next){var rows=Catalog(next).OfType<JsonObject>().ToList();J.Require(rows.Count is >0 and <=50&&rows.Count==Catalog(next).Count,"Use 1–50 activity types",400);J.Require(rows.Select(t=>J.S(t,"id")).Distinct().Count()==rows.Count&&rows.Select(t=>J.S(t,"name").ToUpperInvariant()).Distinct().Count()==rows.Count,"Activity type codes and names must be unique",400);foreach(var t in rows)J.Require(Regex.IsMatch(J.S(t,"id"),"^[a-z][a-z0-9_-]{0,39}$")&&!new[]{"constructor","prototype","__proto__"}.Contains(J.S(t,"id"))&&J.S(t,"name").Trim().Length is >0 and <=80&&t["active"] is JsonValue b&&b.TryGetValue<bool>(out _),"Invalid activity type",400);foreach(var old in Catalog(before).OfType<JsonObject>())J.Require(rows.Any(t=>J.S(t,"id")==J.S(old,"id")),"Deactivate activity types instead of deleting them",400);}
 public static void Project(JsonObject settings,JsonObject row,JsonObject? old){var id=Id(row,"stageType");J.Require(Exists(settings,id),"Unknown project stage",400);if(old is null||id!=Id(old,"stageType"))J.Require(Exists(settings,id,true),"Select an active project stage",400);}
 public static void Task(Snapshot state,JsonObject row,JsonObject? old){string type=Id(row);J.Require(Exists(state.Settings,type),"Unknown activity type",400);if(old is null){var p=state.Records.GetValueOrDefault("project:"+J.S(row,"project"));J.Require(p is not null&&Id(p,"stageType")==type&&Exists(state.Settings,type,true),"New activity type must match the active project stage",400);}else J.Require(type==Id(old),"Saved activity type is permanent; create new work for a new stage",400);
 if(old is null||J.S(row,"activityId")!=J.S(old,"activityId")||J.S(row,"title")!=J.S(old,"title")){var masters=J.A(state.Settings,"activityMaster").ToList();var m=masters.FirstOrDefault(a=>(J.S(row,"activityId")!=""?J.S(a,"id")==J.S(row,"activityId"):J.S(a,"name")==J.S(row,"title"))&&Id(a)==type);J.Require(m is not null&&J.B(m,"active",true)&&J.S(m,"name")==J.S(row,"title"),"Choose an active activity belonging to this type",400);}
 }
 public static void Allocation(Snapshot state,JsonObject task,JsonObject row,JsonObject? prior){var id=Id(row);J.Require(id==Id(task),"Daily allocation type must match its activity",400);if(prior is not null)J.Require(id==Id(prior),"Daily allocation type is permanent",400);else {var p=state.Records.GetValueOrDefault("project:"+J.S(task,"project"));J.Require(p is not null&&id==Id(p,"stageType")&&Exists(state.Settings,id,true),"New daily work must match the active project stage",400);}}
}
